use genewars_runtime::{actor_world::ActorWorld,actor_pool::ActorHandleBindings,actor_activation::TrigTables,creature_world::{CreaturePool,plan_initial_mule_choice,InitialMuleChoice,CreatureError},blueprint::BlueprintRng,player_state::PlayerState};
use std::{fs,io::{BufWriter,Write},path::Path};
fn write(out:&mut impl Write,p:&InitialMuleChoice){out.write_all(&[1]).unwrap();out.write_all(&p.after).unwrap();out.write_all(&p.rng_after.seed.to_le_bytes()).unwrap();out.write_all(&[p.rng_after.ring]).unwrap();out.write_all(&p.rng_after.draw_count.to_le_bytes()).unwrap();out.write_all(&(p.draws.len()as u16).to_le_bytes()).unwrap();out.write_all(&[p.sampled_points.len()as u8]).unwrap();for(point,accepted)in&p.sampled_points{for x in point{out.write_all(&x.to_le_bytes()).unwrap();}out.write_all(&[*accepted as u8]).unwrap();}}
fn main(){
 let arg=std::env::args().nth(1).unwrap();let dir=Path::new(&arg);let bytes=fs::read(dir.join("mission.bin")).unwrap();let source=genewars_assets::ConqMissionSource::parse(&bytes).unwrap();let tables=TrigTables::generate_pinned().unwrap();let pool=CreaturePool::from_mission_source(&source,&[[0;124];300]).unwrap();let before=*pool.record(0).unwrap();
 let world=ActorWorld::from_mission(&source,&[[0;200];20],[ActorHandleBindings::empty();20],core::array::from_fn(|p|PlayerState::fresh_campaign(p as u8,[20736,13568],b"review\0").unwrap()),BlueprintRng{seed:0,ring:31,draw_count:u32::MAX}).unwrap();let mut weights=[0i32;16384];
 for plant in source.group(1).unwrap().bytes().chunks_exact(41){if plant[6]==2&&plant[0x26]&8==0{let x=i16::from_le_bytes(plant[7..9].try_into().unwrap());let y=i16::from_le_bytes(plant[9..11].try_into().unwrap());weights[((y as u16>>8)&127)as usize*128+((x as u16>>8)&127)as usize]+=10;}}
 let mut out=BufWriter::new(fs::File::create(dir.join("all-seeds.bin")).unwrap());
 for seed in 0..=65535u16{let result=plan_initial_mule_choice(&before,BlueprintRng{seed,ring:31,draw_count:u32::MAX},&tables,|point|{let terrain=world.terrain_class_at(point).unwrap();let cell=((point[1]as u16>>8)&127)as usize*128+((point[0]as u16>>8)&127)as usize;Ok(terrain!=0&&weights[cell]<10)});match result{Ok(p)=>write(&mut out,&p),Err(CreatureError::TargetSearchRequired)=>out.write_all(&[0]).unwrap(),Err(e)=>panic!("{e:?}")};}out.flush().unwrap();
 let mut out=BufWriter::new(fs::File::create(dir.join("owned-seeds.bin")).unwrap());
 for seed in (0..64u16).chain([5428,65535]){let mut world=ActorWorld::from_mission(&source,&[[0;200];20],[ActorHandleBindings::empty();20],core::array::from_fn(|p|PlayerState::fresh_campaign(p as u8,[20736,13568],b"review\0").unwrap()),BlueprintRng{seed,ring:31,draw_count:u32::MAX}).unwrap();world.admit_creatures(&[[0;124];300]).unwrap();let snapshot=world.clone();assert!(world.step_initial_mule_choice(0,&tables).is_err());assert_eq!(world,snapshot);let before_backing=world.backing_bytes().to_vec();let before_actors=world.actors().clone();let players=core::array::from_fn::<_,4,_>(|p|world.player(p as u8).unwrap().clone());let p=world.step_initial_mule_choice(1,&tables).unwrap();assert_eq!(world.backing_bytes(),before_backing);assert_eq!(world.actors(),&before_actors);for i in 0..4{assert_eq!(world.player(i as u8).unwrap(),&players[i]);}assert_eq!(world.creatures().unwrap().record(0).unwrap(),&p.after);assert_eq!(world.rng(),p.rng_after);let snapshot=world.clone();assert!(world.step_initial_mule_choice(1,&tables).is_err());assert_eq!(world,snapshot);write(&mut out,&p);}out.flush().unwrap();
 let rng=BlueprintRng{seed:5428,ring:31,draw_count:u32::MAX};assert!(matches!(plan_initial_mule_choice(&before,rng,&tables,|_|Ok(false)),Err(CreatureError::TargetSearchRequired)));let mut changed=before;changed[6]=2;let mut calls=0;assert!(plan_initial_mule_choice(&changed,rng,&tables,|_|{calls+=1;Ok(true)}).is_err());assert_eq!(calls,0);
}
